import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"第三阶段 · 桌面操作","description":"让 Hearth 操作没有开放接口的桌面软件和跨应用流程。","frontmatter":{"title":"第三阶段 · 桌面操作","description":"让 Hearth 操作没有开放接口的桌面软件和跨应用流程。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3.md","filePath":"delivery/stage-3.md","lastUpdated":1793859143000}'),l={name:"delivery/stage-3.md"};function i(h,t,o,s,n,_){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第三阶段-·-桌面操作" tabindex="-1">第三阶段 · 桌面操作 <a class="header-anchor" href="#第三阶段-·-桌面操作" aria-label="Permalink to &quot;第三阶段 · 桌面操作&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第三阶段让 Hearth 能操作没有开放接口的桌面软件和跨应用流程。顺序是先看见、再接管、再低风险操作，最后才开放高风险操作。任何无法观察、无法暂停或无法接管的情况，都不允许自动执行。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-3/3-1.html">3.1 连接并查看桌面设备</a></td><td>让用户看清设备、权限范围和停止入口。</td></tr><tr><td><a href="/hearth-os/delivery/stage-3/3-2.html">3.2 观察桌面与人工接管</a></td><td>让用户看见操作过程，并能暂停、接管和交还。</td></tr><tr><td><a href="/hearth-os/delivery/stage-3/3-3.html">3.3 分级完成桌面操作</a></td><td>低风险先做，高风险必须可预览、可确认、可恢复。</td></tr><tr><td><a href="/hearth-os/delivery/stage-3/3-4.html">3.4 验收桌面操作</a></td><td>用真实桌面任务证明可看懂、可接管、可停止。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先让用户看到并信任桌面设备。</li><li>再让用户能观察、暂停和接管操作。</li><li>然后在白名单应用内完成低风险操作。</li><li>最后才开放高风险操作，并准备快照、补偿和恢复演练。</li></ol>',7)])])}const m=e(l,[["render",i]]);export{p as __pageData,m as default};
